export const stories_a1 = [{"id":"a1_1","level":"A1","topic":"daily life","title":"My Afternoon Routine","titleVi":"Thói Quen Buổi Chiều Của Tôi","illustrationEmoji":"🌤️","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: thói quen buổi chiều của tôi.","englishText":"After school, I go home and **have** a small snack. I usually **eat** fruit or drink a glass of milk.\n\nThen I **do** my homework. I sit at my desk and **write** in my notebook. Math is my favorite subject. I **finish** my homework in one hour.\n\nAfter homework, I have free time. I **play** badminton with my brother in the yard. We **enjoy** playing together.\n\nAt five o'clock, I **take** a shower. Then I **help** my mother set the **table** for dinner.\n\nIn the evening, I **watch** TV or **read** a book before bed. I go to bed at nine o'clock.","vietnameseText":"Sau giờ học, tôi về nhà và **ăn** một bữa nhẹ. Tôi thường **ăn** trái cây hoặc uống một ly sữa.\n\nSau đó tôi **làm** bài tập về nhà. Tôi ngồi ở bàn và **viết** vào vở. Toán là môn yêu thích của tôi. Tôi **hoàn thành** bài tập trong một giờ.\n\nSau bài tập, tôi có thời gian rảnh. Tôi **chơi** cầu lông với anh trai ngoài sân. Chúng tôi **thích** chơi cùng nhau.\n\nLúc năm giờ, tôi **đi** tắm. Sau đó tôi **giúp** mẹ **dọn** bàn ăn tối.\n\nBuổi tối, tôi **xem** TV hoặc **đọc** sách trước khi đi ngủ. Tôi đi ngủ lúc chín giờ.","vocabularyFocus":[{"word":"have a snack","vi":"ăn nhẹ","example":"I have a snack after school."},{"word":"do homework","vi":"làm bài tập","example":"I do my homework every day."},{"word":"write","vi":"viết","example":"I write in my notebook."},{"word":"finish","vi":"hoàn thành","example":"I finish my work."},{"word":"play badminton","vi":"chơi cầu lông","example":"We play badminton."},{"word":"enjoy","vi":"thích, tận hưởng","example":"We enjoy playing."},{"word":"take a shower","vi":"đi tắm","example":"I take a shower."},{"word":"help","vi":"giúp đỡ","example":"I help my mother."}],"phrases":[{"en":"go home after school","vi":"về nhà sau giờ học"},{"en":"sit at my desk","vi":"ngồi ở bàn học"},{"en":"free time","vi":"thời gian rảnh"},{"en":"set the table","vi":"dọn bàn ăn"},{"en":"before bed","vi":"trước khi đi ngủ"}],"comprehensionQuestions":[{"question":"What does the writer do after school?","options":["Plays outside","Has a snack","Goes to bed","Watches TV"],"correct":1},{"question":"How long does homework take?","options":["30 minutes","One hour","Two hours","Three hours"],"correct":1},{"question":"What sport does the writer play?","options":["Soccer","Badminton","Tennis","Volleyball"],"correct":1},{"question":"What time does the writer take a shower?","options":["4:00","5:00","6:00","7:00"],"correct":1},{"question":"What does the writer do before bed?","options":["Plays games","Reads a book","Exercises","Eats"],"correct":1}],"answers":[1,1,1,1,1],"answerExplanationVi":"1. Ăn nhẹ sau giờ học. 2. Bài tập mất một giờ. 3. Chơi cầu lông. 4. Tắm lúc năm giờ. 5. Đọc sách trước khi ngủ.","discussionQuestions":["Bạn thường làm gì sau giờ học?","Bạn có giúp bố mẹ việc nhà không?","Bạn thích chơi môn thể thao nào?"],"grammarFocus":{"point":"Present Simple for Routines","explanation":"Thì hiện tại đơn dùng để diễn tả thói quen hằng ngày. Ví dụ: \"I do my homework every day.\" (Tôi làm bài tập mỗi ngày.)"},"shadowingSentences":["After school, I have a small snack.","I do my homework at my desk.","I finish my homework in one hour.","I play badminton with my brother.","I go to bed at nine o'clock."]},{"id":"a1_2","level":"A1","topic":"school","title":"My Favorite Subject","titleVi":"Môn Học Yêu Thích Của Tôi","illustrationEmoji":"📐","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: môn học yêu thích của tôi.","englishText":"My favorite subject in school is **English**. I like it because it is **useful** and **fun**. I can learn new **words** every day.\n\nMy English teacher is Ms. Lan. She is very **kind**. She always **explains** the lesson slowly and clearly. She **helps** us when we make **mistakes**.\n\nIn English class, we **read** short stories and **write** sentences. We also **listen** to songs and **sing** along. I enjoy speaking English with my classmates.\n\nI practice English at home too. I **watch** cartoons in English. I **learn** five new words every day.\n\nI want to be **fluent** in English one day. I want to **travel** and talk to people from other countries.","vietnameseText":"Môn học yêu thích của tôi ở trường là **tiếng Anh**. Tôi thích nó vì nó **hữu ích** và **vui**. Tôi có thể học từ **mới** mỗi ngày.\n\nGiáo viên tiếng Anh của tôi là cô Lan. Cô ấy rất **tốt bụng**. Cô ấy luôn **giải thích** bài học chậm và rõ ràng. Cô ấy **giúp đỡ** chúng tôi khi chúng tôi mắc **lỗi**.\n\nTrong lớp tiếng Anh, chúng tôi **đọc** truyện ngắn và **viết** câu. Chúng tôi cũng **nghe** bài hát và **hát** theo. Tôi thích nói tiếng Anh với các bạn cùng lớp.\n\nTôi cũng luyện tiếng Anh ở nhà. Tôi **xem** phim hoạt hình bằng tiếng Anh. Tôi **học** năm từ mới mỗi ngày.\n\nTôi muốn **thông thạo** tiếng Anh một ngày nào đó. Tôi muốn **đi du lịch** và nói chuyện với người từ các quốc gia khác.","vocabularyFocus":[{"word":"English","vi":"tiếng Anh","example":"I study English."},{"word":"useful","vi":"hữu ích","example":"It is useful."},{"word":"word","vi":"từ","example":"Learn new words."},{"word":"explain","vi":"giải thích","example":"She explains the lesson."},{"word":"mistake","vi":"lỗi, sai sót","example":"I made a mistake."},{"word":"listen","vi":"nghe","example":"Listen to songs."},{"word":"fluent","vi":"thông thạo","example":"I want to be fluent."},{"word":"travel","vi":"đi du lịch","example":"I want to travel."}],"phrases":[{"en":"my favorite subject","vi":"môn học yêu thích của tôi"},{"en":"slowly and clearly","vi":"chậm và rõ ràng"},{"en":"make mistakes","vi":"mắc lỗi"},{"en":"sing along","vi":"hát theo"},{"en":"talk to people","vi":"nói chuyện với mọi người"}],"comprehensionQuestions":[{"question":"What is the writer's favorite subject?","options":["Math","English","Science","Art"],"correct":1},{"question":"What is Ms. Lan like?","options":["Strict","Kind","Quiet","Serious"],"correct":1},{"question":"What does the class NOT do?","options":["Read stories","Write sentences","Draw pictures","Listen to songs"],"correct":2},{"question":"How many new words does the writer learn daily?","options":["Three","Four","Five","Ten"],"correct":2},{"question":"Why does the writer want to be fluent?","options":["For exams","To travel and talk to people","For work","To watch movies"],"correct":1}],"answers":[1,1,2,2,1],"answerExplanationVi":"1. Môn yêu thích là tiếng Anh. 2. Cô Lan tốt bụng. 3. Lớp không vẽ tranh. 4. Học năm từ mới mỗi ngày. 5. Để du lịch và nói chuyện.","discussionQuestions":["Môn học yêu thích của bạn là gì?","Bạn học tiếng Anh như thế nào?","Bạn có muốn đi du lịch nước ngoài không?"],"grammarFocus":{"point":"Want to + Verb","explanation":"Cấu trúc \"want to\" (muốn) + động từ. Ví dụ: \"I want to be fluent.\" (Tôi muốn thông thạo.) \"She wants to travel.\" (Cô ấy muốn du lịch.)"},"shadowingSentences":["My favorite subject is English.","My teacher explains the lesson clearly.","We read stories and write sentences.","I watch cartoons in English.","I want to be fluent in English."]},{"id":"a1_3","level":"A1","topic":"food","title":"The Fruit Stall","titleVi":"Quầy Trái Cây","illustrationEmoji":"🍎","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: quầy trái cây.","englishText":"Every morning, my mother goes to the fruit **stall** near our house. The seller is a **friendly** old woman. She sells many kinds of fruit: **bananas**, **oranges**, apples, and mangoes. The fruit is always **fresh**. My mother buys bananas and oranges every day. Sometimes she buys apples for me. I like apples because they are **sweet** and **healthy**. Eating fruit every day is good for your body.","vietnameseText":"Mỗi buổi sáng, mẹ tôi đi đến **quầy** trái cây gần nhà. Người bán là một bà lão **thân thiện**. Bà bán nhiều loại trái cây: **chuối**, **cam**, táo và xoài. Trái cây luôn **tươi**. Mẹ tôi mua chuối và cam mỗi ngày. Thỉnh thoảng bà mua táo cho tôi. Tôi thích táo vì chúng **ngọt** và **tốt cho sức khỏe**. Ăn trái cây mỗi ngày tốt cho cơ thể của bạn.","vocabularyFocus":[{"word":"stall","vi":"quầy hàng","example":""},{"word":"friendly","vi":"thân thiện","example":""},{"word":"banana","vi":"chuối","example":""},{"word":"orange","vi":"cam","example":""},{"word":"fresh","vi":"tươi","example":""},{"word":"sweet","vi":"ngọt","example":""},{"word":"healthy","vi":"tốt cho sức khỏe","example":""},{"word":"every day","vi":"mỗi ngày","example":""}],"phrases":[{"en":"near our house","vi":"gần nhà chúng tôi"},{"en":"many kinds of fruit","vi":"nhiều loại trái cây"},{"en":"good for your body","vi":"tốt cho cơ thể"},{"en":"every morning","vi":"mỗi buổi sáng"},{"en":"sells many kinds","vi":"bán nhiều loại"}],"comprehensionQuestions":[{"question":"Where is the fruit stall?","options":["At the market","Near their house","In the city","At school"],"correct":1},{"question":"What does the seller look like?","options":["A young girl","An old woman","A man","A boy"],"correct":1},{"question":"What fruit does the writer like?","options":["Bananas","Oranges","Apples","Mangoes"],"correct":2},{"question":"How often does mother buy fruit?","options":["Every day","Every week","Once a month","Never"],"correct":0},{"question":"Why is eating fruit good?","options":["It is cheap","It is healthy","It is fun","It is easy"],"correct":1}],"answers":[1,1,2,0,1],"answerExplanationVi":"1. Gần nhà. 2. Bà lão. 3. Thích táo. 4. Mỗi ngày. 5. Tốt cho sức khỏe.","discussionQuestions":["Bạn thích ăn trái cây gì?","Bạn có thường ăn trái cây không?","Trái cây nào tốt cho sức khỏe?"],"grammarFocus":{"point":"Adjectives for Describing","explanation":"Tính từ dùng để miêu tả: \"friendly\" (thân thiện), \"fresh\" (tươi), \"sweet\" (ngọt), \"healthy\" (lành mạnh)."},"shadowingSentences":["My mother goes to the fruit stall.","The seller is a friendly old woman.","The fruit is always fresh.","Apples are sweet and healthy.","Eating fruit every day is good."]},{"id":"a1_4","level":"A1","topic":"family","title":"My Uncle's Farm","titleVi":"Trang Trại Của Chú Tôi","illustrationEmoji":"🚜","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: trang trại của chú tôi.","englishText":"My uncle has a **farm** in the countryside. It is big and **beautiful**. He grows **rice** and **vegetables**. He also has cows, chickens, and pigs. Every summer, my family **visits** his farm. I love to **feed** the chickens. They are very **funny**. My uncle **teaches** me how to grow vegetables. He gives us fresh eggs and rice when we leave. I like the farm because it is **quiet** and the air is **clean**.","vietnameseText":"Chú tôi có một **trang trại** ở vùng quê. Nó rộng và **đẹp**. Chú trồng **lúa** và **rau**. Chú cũng có bò, gà và heo. Mỗi mùa hè, gia đình tôi **đến thăm** trang trại của chú. Tôi thích **cho** gà ăn. Chúng rất **buồn cười**. Chú tôi **dạy** tôi cách trồng rau. Chú cho chúng tôi trứng và gạo tươi khi chúng tôi về. Tôi thích trang trại vì nó **yên tĩnh** và không khí **trong lành**.","vocabularyFocus":[{"word":"farm","vi":"trang trại","example":""},{"word":"beautiful","vi":"đẹp","example":""},{"word":"rice","vi":"lúa, gạo","example":""},{"word":"vegetables","vi":"rau củ","example":""},{"word":"visit","vi":"đến thăm","example":""},{"word":"feed","vi":"cho ăn","example":""},{"word":"teach","vi":"dạy","example":""},{"word":"quiet","vi":"yên tĩnh","example":""},{"word":"clean","vi":"sạch sẽ, trong lành","example":""}],"phrases":[{"en":"in the countryside","vi":"ở vùng quê"},{"en":"grows rice and vegetables","vi":"trồng lúa và rau"},{"en":"every summer","vi":"mỗi mùa hè"},{"en":"fresh eggs","vi":"trứng tươi"},{"en":"the air is clean","vi":"không khí trong lành"}],"comprehensionQuestions":[{"question":"Where is the farm?","options":["In the city","In the countryside","Near the sea","In the mountains"],"correct":1},{"question":"What animals does the uncle have?","options":["Dogs and cats","Cows, chickens, pigs","Horses and sheep","Ducks and goats"],"correct":1},{"question":"When does the writer visit?","options":["Winter","Summer","Spring","Fall"],"correct":1},{"question":"What does the uncle teach?","options":["How to cook","How to grow vegetables","How to drive","How to swim"],"correct":1},{"question":"Why does the writer like the farm?","options":["It is noisy","It is quiet and clean","It is far","It is big"],"correct":1}],"answers":[1,1,1,1,1],"answerExplanationVi":"1. Ở vùng quê. 2. Bò, gà, heo. 3. Mùa hè. 4. Dạy trồng rau. 5. Yên tĩnh và trong lành.","discussionQuestions":["Bạn đã đến thăm trang trại bao giờ chưa?","Bạn muốn nuôi con vật gì?","Bạn thích không khí ở nông thôn hay thành phố?"],"grammarFocus":{"point":"Has/Have for Possession","explanation":"\"Has\" (có) dùng với chủ ngữ số ít (he/she/it). \"Have\" dùng với I/you/we/they. Ví dụ: \"My uncle has a farm.\" (Chú tôi có một trang trại.)"},"shadowingSentences":["My uncle has a big farm.","He grows rice and vegetables.","I love to feed the chickens.","The air is clean in the countryside.","I like the farm very much."]},{"id":"a1_5","level":"A1","topic":"school","title":"My Classroom","titleVi":"Lớp Học Của Tôi","illustrationEmoji":"🪑","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: lớp học của tôi.","englishText":"My classroom is on the second **floor**. It is big and **bright**. There are twenty desks and chairs. The walls are **yellow**. There is a big **board** in front. Our teacher writes on it. There are also **posters** of animals and maps on the walls. I sit near the **window**. I can see a big tree from my seat. I like my classroom because it is **clean** and comfortable.","vietnameseText":"Phòng học của tôi ở **tầng** hai. Nó rộng và **sáng sủa**. Có hai mươi bộ bàn ghế. Tường màu **vàng**. Có một **bảng** lớn ở phía trước. Giáo viên viết lên đó. Cũng có những tấm **áp phích** về động vật và bản đồ trên tường. Tôi ngồi gần **cửa sổ**. Tôi có thể thấy một cây lớn từ chỗ ngồi của mình. Tôi thích phòng học vì nó **sạch sẽ** và thoải mái.","vocabularyFocus":[{"word":"floor","vi":"tầng","example":""},{"word":"bright","vi":"sáng sủa","example":""},{"word":"board","vi":"bảng","example":""},{"word":"poster","vi":"áp phích","example":""},{"word":"window","vi":"cửa sổ","example":""},{"word":"desk","vi":"bàn học","example":""},{"word":"clean","vi":"sạch sẽ","example":""},{"word":"comfortable","vi":"thoải mái","example":""}],"phrases":[{"en":"on the second floor","vi":"ở tầng hai"},{"en":"big and bright","vi":"to và sáng sủa"},{"en":"near the window","vi":"gần cửa sổ"},{"en":"posters of animals","vi":"áp phích động vật"},{"en":"clean and comfortable","vi":"sạch và thoải mái"}],"comprehensionQuestions":[{"question":"What floor is the classroom on?","options":["First","Second","Third","Fourth"],"correct":1},{"question":"What color are the walls?","options":["White","Blue","Yellow","Green"],"correct":2},{"question":"Where does the writer sit?","options":["Near the door","Near the window","In the back","In front"],"correct":1},{"question":"What is on the walls?","options":["Photos","Posters and maps","Paintings","Flags"],"correct":1},{"question":"Why does the writer like the classroom?","options":["It is big","It is clean and comfortable","It has many students","It is new"],"correct":1}],"answers":[1,2,1,1,1],"answerExplanationVi":"1. Tầng hai. 2. Tường màu vàng. 3. Gần cửa sổ. 4. Áp phích và bản đồ. 5. Sạch và thoải mái.","discussionQuestions":["Lớp học của bạn thế nào?","Bạn thích ngồi ở đâu trong lớp?","Phòng học lý tưởng của bạn là gì?"],"grammarFocus":{"point":"Present Simple vs Present Continuous","explanation":"Hiện tại đơn (thói quen) vs Hiện tại tiếp diễn (đang xảy ra). \"I usually eat fruit\" (thường ăn) vs \"I am eating now\" (đang ăn)."},"shadowingSentences":["My classroom is on the second floor.","It is big and bright.","There are twenty desks and chairs.","I sit near the window.","I like my classroom because it is clean."]},{"id":"a1_6","level":"A1","topic":"travel","title":"A Trip to the Beach","titleVi":"Một Chuyến Đi Biển","illustrationEmoji":"🏖️","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: một chuyến đi biển.","englishText":"Last weekend, my family went to the **beach**. It was a sunny day. The water was **warm** and clean. My sister and I **swam** in the sea. We also built a **sandcastle**. It had a big tower. My father took many **photos**. My mother read a book under an **umbrella**. We ate seafood for lunch. The fish was delicious. I felt very **happy** at the beach.","vietnameseText":"Cuối tuần trước, gia đình tôi đã đi **biển**. Đó là một ngày nắng đẹp. Nước **ấm** và sạch. Chị tôi và tôi đã **bơi** ở biển. Chúng tôi cũng xây một **lâu đài cát**. Nó có một tòa tháp lớn. Bố tôi đã chụp nhiều **ảnh**. Mẹ tôi đọc sách dưới **ô**. Chúng tôi ăn hải sản cho bữa trưa. Cá rất ngon. Tôi cảm thấy rất **vui vẻ** ở biển.","vocabularyFocus":[{"word":"beach","vi":"bãi biển","example":""},{"word":"warm","vi":"ấm","example":""},{"word":"swim","vi":"bơi","example":""},{"word":"sandcastle","vi":"lâu đài cát","example":""},{"word":"photo","vi":"ảnh","example":""},{"word":"umbrella","vi":"ô, dù","example":""},{"word":"seafood","vi":"hải sản","example":""},{"word":"happy","vi":"vui vẻ","example":""}],"phrases":[{"en":"last weekend","vi":"cuối tuần trước"},{"en":"went to the beach","vi":"đã đi biển"},{"en":"built a sandcastle","vi":"đã xây lâu đài cát"},{"en":"took many photos","vi":"đã chụp nhiều ảnh"},{"en":"felt very happy","vi":"cảm thấy rất vui"}],"comprehensionQuestions":[{"question":"Where did the family go?","options":["The mountains","The beach","The park","The market"],"correct":1},{"question":"What did they build?","options":["A house","A sandcastle","A tent","A fire"],"correct":1},{"question":"What did they eat for lunch?","options":["Sandwiches","Seafood","Pizza","Noodles"],"correct":1},{"question":"What did the father do?","options":["Swam","Took photos","Read a book","Slept"],"correct":1},{"question":"How was the weather?","options":["Rainy","Windy","Sunny","Cold"],"correct":2}],"answers":[1,1,1,1,2],"answerExplanationVi":"1. Đi biển. 2. Xây lâu đài cát. 3. Ăn hải sản. 4. Chụp ảnh. 5. Trời nắng.","discussionQuestions":["Bạn thích đi biển hay đi núi?","Bạn thường làm gì ở biển?","Kỳ nghỉ biển đáng nhớ nhất của bạn?"],"grammarFocus":{"point":"Prepositions of Time","explanation":"\"At\" (at 5 o'clock), \"in\" (in the morning/summer), \"on\" (on Monday). Dùng để chỉ thời gian."},"shadowingSentences":["Last weekend, my family went to the beach.","It was a sunny day.","My sister and I swam in the sea.","We also built a sandcastle.","I felt very happy at the beach."]},{"id":"a1_7","level":"A1","topic":"health","title":"Staying Healthy","titleVi":"Giữ Gìn Sức Khỏe","illustrationEmoji":"🍎","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: giữ gìn sức khỏe.","englishText":"I want to stay **healthy**. I eat vegetables and fruit every day. I **drink** a lot of water. I **exercise** for 30 minutes every morning. I usually **jog** in the park near my house. I also **sleep** eight hours every night. I do not eat too much **candy** or junk food. Being healthy makes me feel **energetic** and happy. I can study and play better.","vietnameseText":"Tôi muốn giữ gìn **sức khỏe**. Tôi ăn rau củ và trái cây mỗi ngày. Tôi **uống** nhiều nước. Tôi **tập thể dục** 30 phút mỗi sáng. Tôi thường **chạy bộ** trong công viên gần nhà. Tôi cũng **ngủ** tám tiếng mỗi đêm. Tôi không ăn quá nhiều **kẹo** hay đồ ăn vặt. Khỏe mạnh giúp tôi cảm thấy **tràn đầy năng lượng** và vui vẻ.","vocabularyFocus":[{"word":"healthy","vi":"khỏe mạnh","example":""},{"word":"drink","vi":"uống","example":""},{"word":"exercise","vi":"tập thể dục","example":""},{"word":"jog","vi":"chạy bộ","example":""},{"word":"sleep","vi":"ngủ","example":""},{"word":"candy","vi":"kẹo","example":""},{"word":"energetic","vi":"tràn đầy năng lượng","example":""},{"word":"every day","vi":"mỗi ngày","example":""}],"phrases":[{"en":"stay healthy","vi":"giữ gìn sức khỏe"},{"en":"eat vegetables and fruit","vi":"ăn rau củ và trái cây"},{"en":"every morning","vi":"mỗi buổi sáng"},{"en":"drink a lot of water","vi":"uống nhiều nước"},{"en":"feel energetic","vi":"cảm thấy tràn đầy năng lượng"}],"comprehensionQuestions":[{"question":"How long does the writer exercise each morning?","options":["15 minutes","30 minutes","45 minutes","1 hour"],"correct":1},{"question":"What does the writer NOT do to stay healthy?","options":["Eat vegetables","Drink water","Exercise","Eat candy"],"correct":3},{"question":"How many hours does the writer sleep?","options":["6","7","8","9"],"correct":2},{"question":"Where does the writer jog?","options":["On the street","At school","In the park","At the gym"],"correct":2},{"question":"How does being healthy make the writer feel?","options":["Tired","Energetic","Sleepy","Hungry"],"correct":1}],"answers":[1,3,2,2,1],"answerExplanationVi":"1. 30 phút. 2. Không ăn kẹo. 3. Ngủ 8 tiếng. 4. Trong công viên. 5. Tràn đầy năng lượng.","discussionQuestions":["Bạn làm gì để giữ sức khỏe?","Bạn tập thể dục bao lâu một lần?","Món ăn lành mạnh yêu thích của bạn?"],"grammarFocus":{"point":"Can/Can't","explanation":"\"Can\" (có thể) + động từ. Ví dụ: \"I can swim.\" (Tôi có thể bơi.) \"I can't fly.\" (Tôi không thể bay.)"},"shadowingSentences":["I want to stay healthy.","I exercise for 30 minutes every morning.","I jog in the park near my house.","I sleep eight hours every night.","Being healthy makes me feel energetic."]},{"id":"a1_8","level":"A1","topic":"daily life","title":"My Hobbies","titleVi":"Sở Thích Của Tôi","illustrationEmoji":"🎨","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: sở thích của tôi.","englishText":"I have many **hobbies**. My favorite hobby is **drawing**. I draw animals, flowers, and my family. I also like to **collect** stamps. I have stamps from many countries. On weekends, I sometimes **play** the guitar. I am still a **beginner**, but I can play simple songs. I also like to **read** comic books. My hobbies make my free time **fun** and interesting.","vietnameseText":"Tôi có nhiều **sở thích**. Sở thích yêu thích nhất là **vẽ**. Tôi vẽ động vật, hoa lá và gia đình tôi. Tôi cũng thích **sưu tập** tem. Tôi có tem từ nhiều quốc gia. Vào cuối tuần, đôi khi tôi **chơi** guitar. Tôi vẫn là **người mới bắt đầu**, nhưng tôi có thể chơi những bài đơn giản. Tôi cũng thích **đọc** truyện tranh. Sở thích của tôi làm thời gian rảnh của tôi trở nên **thú vị**.","vocabularyFocus":[{"word":"hobby","vi":"sở thích","example":""},{"word":"drawing","vi":"vẽ","example":""},{"word":"collect","vi":"sưu tập","example":""},{"word":"stamp","vi":"tem","example":""},{"word":"guitar","vi":"guitar","example":""},{"word":"beginner","vi":"người mới bắt đầu","example":""},{"word":"comic","vi":"truyện tranh","example":""},{"word":"free time","vi":"thời gian rảnh","example":""}],"phrases":[{"en":"favorite hobby","vi":"sở thích yêu thích"},{"en":"draw animals and flowers","vi":"vẽ động vật và hoa"},{"en":"collect stamps","vi":"sưu tập tem"},{"en":"play the guitar","vi":"chơi guitar"},{"en":"free time","vi":"thời gian rảnh"}],"comprehensionQuestions":[{"question":"What is the writer's favorite hobby?","options":["Singing","Drawing","Dancing","Cooking"],"correct":1},{"question":"What does the writer collect?","options":["Coins","Stamps","Cards","Toys"],"correct":1},{"question":"What instrument does the writer play?","options":["Piano","Violin","Guitar","Drums"],"correct":2},{"question":"When does the writer play guitar?","options":["Every day","On weekends","Never","In the morning"],"correct":1},{"question":"What type of books does the writer read?","options":["Textbooks","Comic books","Novels","Magazines"],"correct":1}],"answers":[1,1,2,1,1],"answerExplanationVi":"1. Vẽ. 2. Sưu tập tem. 3. Guitar. 4. Cuối tuần. 5. Truyện tranh.","discussionQuestions":["Sở thích của bạn là gì?","Bạn dành bao nhiêu thời gian cho sở thích?","Bạn muốn học sở thích mới nào không?"],"grammarFocus":{"point":"Like + -ing","explanation":"\"Like + V-ing\" (thích làm gì). Ví dụ: \"I like playing soccer.\" (Tôi thích chơi bóng đá.) \"She likes reading books.\""},"shadowingSentences":["I have many hobbies.","My favorite hobby is drawing.","I also like to collect stamps.","I sometimes play the guitar.","My hobbies make my free time fun."]},{"id":"a1_9","level":"A1","topic":"food","title":"Vietnamese Street Food","titleVi":"Ốc Vỉa Hè Việt Nam","illustrationEmoji":"🍜","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: ốc vỉa hè việt nam.","englishText":"Vietnamese **street food** is very delicious. My favorite is **banh mi** – a bread with meat, vegetables, and sauce. It costs only 15,000 dong. I also like **banh xeo** – crispy pancakes with shrimp. On the way home from school, I often buy **che** – a sweet dessert drink. The street food sellers are very **friendly**. They always **smile**. I think Vietnamese street food is the best in the world.","vietnameseText":"**Ốc vỉa hè** Việt Nam rất ngon. Món yêu thích của tôi là **bánh mì** – bánh mì với thịt, rau và sốt. Nó chỉ có 15.000 đồng. Tôi cũng thích **bánh xèo** – bánh pancake giòn với tôm. Trên đường đi học về, tôi thường mua **chè** – một thức uống tráng miệng ngọt. Những người bán ốc vỉa hè rất **thân thiện**. Họ luôn **mỉm cười**. Tôi nghĩ ốc vỉa hè Việt Nam là tuyệt nhất thế giới.","vocabularyFocus":[{"word":"street food","vi":"ốc vỉa hè","example":""},{"word":"banh mi","vi":"bánh mì","example":""},{"word":"crispy","vi":"giòn","example":""},{"word":"pancake","vi":"bánh pancake","example":""},{"word":"sweet","vi":"ngọt","example":""},{"word":"seller","vi":"người bán","example":""},{"word":"friendly","vi":"thân thiện","example":""},{"word":"smile","vi":"mỉm cười","example":""}],"phrases":[{"en":"very delicious","vi":"rất ngon"},{"en":"on the way home","vi":"trên đường về nhà"},{"en":"costs 15,000 dong","vi":"giá 15.000 đồng"},{"en":"street food sellers","vi":"người bán ốc vỉa hè"},{"en":"the best in the world","vi":"tuyệt nhất thế giới"}],"comprehensionQuestions":[{"question":"What is the writer's favorite street food?","options":["Pho","Banh mi","Bun cha","Com tam"],"correct":1},{"question":"How much does banh mi cost?","options":["10,000 dong","15,000 dong","20,000 dong","25,000 dong"],"correct":1},{"question":"What is banh xeo?","options":["A soup","A crispy pancake","A noodle dish","A drink"],"correct":1},{"question":"What does the writer buy on the way home?","options":["Banh mi","Banh xeo","Che","Pho"],"correct":2},{"question":"How are the sellers?","options":["Rude","Friendly","Quiet","Strict"],"correct":1}],"answers":[1,1,1,2,1],"answerExplanationVi":"1. Bánh mì. 2. 15.000 đồng. 3. Bánh pancake giòn. 4. Chè. 5. Thân thiện.","discussionQuestions":["Món ăn đường phố yêu thích của bạn là gì?","Bạn thích ăn vặt không?","Món Việt Nam nào bạn muốn giới thiệu với bạn quốc tế?"],"grammarFocus":{"point":"Question Words (What/Where/When)","explanation":"Từ để hỏi: \"What\" (gì), \"Where\" (ở đâu), \"When\" (khi nào), \"Who\" (ai), \"Why\" (tại sao)."},"shadowingSentences":["My favorite is banh mi.","It costs only 15,000 dong.","I also like banh xeo.","The sellers are very friendly.","I think Vietnamese street food is the best."]},{"id":"a1_10","level":"A1","topic":"family","title":"My Baby Brother","titleVi":"Em Trai Nhỏ Của Tôi","illustrationEmoji":"👶","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: em trai nhỏ của tôi.","englishText":"I have a baby **brother**. He is only two years old. His name is Bi. He is very **cute**. He has round eyes and chubby **cheeks**. He likes to **play** with toys. He throws his toys everywhere. He also likes to **watch** cartoons on TV. Sometimes he **cries** when he is hungry. I help my mother **feed** him. I love my baby brother very much.","vietnameseText":"Tôi có một **em trai** nhỏ. Em ấy mới hai tuổi. Tên em ấy là Bi. Em ấy rất **dễ thương**. Em ấy có mắt tròn và **má** phúng phính. Em ấy thích **chơi** đồ chơi. Em ấy ném đồ chơi khắp nơi. Em ấy cũng thích **xem** phim hoạt hình trên TV. Đôi khi em ấy **khóc** khi đói. Tôi giúp mẹ **cho** em ấy ăn. Tôi rất yêu em trai nhỏ của tôi.","vocabularyFocus":[{"word":"brother","vi":"em trai","example":""},{"word":"cute","vi":"dễ thương","example":""},{"word":"cheeks","vi":"má","example":""},{"word":"toys","vi":"đồ chơi","example":""},{"word":"cartoon","vi":"phim hoạt hình","example":""},{"word":"cry","vi":"khóc","example":""},{"word":"hungry","vi":"đói","example":""},{"word":"feed","vi":"cho ăn","example":""}],"phrases":[{"en":"two years old","vi":"hai tuổi"},{"en":"very cute","vi":"rất dễ thương"},{"en":"throws his toys","vi":"ném đồ chơi của em ấy"},{"en":"watches cartoons","vi":"xem phim hoạt hình"},{"en":"help my mother feed him","vi":"giúp mẹ cho em ấy ăn"}],"comprehensionQuestions":[{"question":"How old is the writer's baby brother?","options":["One","Two","Three","Four"],"correct":1},{"question":"What does the baby look like?","options":["Tall and thin","Round eyes, chubby cheeks","Small and blond","Curly hair"],"correct":1},{"question":"What does the baby do when hungry?","options":["Laughs","Cries","Sleeps","Plays"],"correct":1},{"question":"What does the writer help do?","options":["Feed the baby","Dress the baby","Teach the baby","Walk the baby"],"correct":0},{"question":"How does the writer feel about the baby?","options":["Annoyed","Loves him","Jealous","Indifferent"],"correct":1}],"answers":[1,1,1,0,1],"answerExplanationVi":"1. Hai tuổi. 2. Mắt tròn, má phúng phính. 3. Khóc. 4. Cho ăn. 5. Yêu em.","discussionQuestions":["Bạn có em trai/em gái không?","Em bạn bao nhiêu tuổi?","Bạn giúp bố mẹ trông em như thế nào?"],"grammarFocus":{"point":"Have to / Must","explanation":"\"Have to\" (phải làm gì). Ví dụ: \"I have to do my homework.\" (Tôi phải làm bài tập.) \"She has to go now.\""},"shadowingSentences":["I have a baby brother.","He is only two years old.","He is very cute.","He has round eyes and chubby cheeks.","I love my baby brother very much."]},{"id":"a1_11","level":"A1","topic":"school","title":"The School Library","titleVi":"Thư Viện Trường Học","illustrationEmoji":"📖","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: thư viện trường học.","englishText":"Our school **library** is a quiet place. It has many **books**: story books, picture books, and science books. The librarian is Mrs. Hoa. She is very **helpful**. Every Wednesday, our class visits the library. I like to **read** adventure stories. I also **borrow** books to read at home. The library helps me **learn** new things and improve my reading.","vietnameseText":"**Thư viện** trường chúng tôi là một nơi yên tĩnh. Nó có nhiều **sách**: sách truyện, sách tranh và sách khoa học. Người thủ thư là cô Hoa. Cô ấy rất **hay giúp đỡ**. Mỗi thứ Tư, lớp chúng tôi đến thăm thư viện. Tôi thích **đọc** truyện phiêu lưu. Tôi cũng **mượn** sách về nhà đọc. Thư viện giúp tôi **học** những điều mới và cải thiện kỹ năng đọc.","vocabularyFocus":[{"word":"library","vi":"thư viện","example":""},{"word":"quiet","vi":"yên tĩnh","example":""},{"word":"books","vi":"sách","example":""},{"word":"librarian","vi":"thủ thư","example":""},{"word":"helpful","vi":"hay giúp đỡ","example":""},{"word":"adventure","vi":"phiêu lưu","example":""},{"word":"borrow","vi":"mượn","example":""},{"word":"reading","vi":"đọc sách","example":""}],"phrases":[{"en":"a quiet place","vi":"nơi yên tĩnh"},{"en":"many books","vi":"nhiều sách"},{"en":"every Wednesday","vi":"mỗi thứ Tư"},{"en":"read adventure stories","vi":"đọc truyện phiêu lưu"},{"en":"improve my reading","vi":"cải thiện kỹ năng đọc"}],"comprehensionQuestions":[{"question":"Who is the librarian?","options":["Mrs. Mai","Mrs. Hoa","Mrs. Lan","Mr. Minh"],"correct":1},{"question":"When does the class visit the library?","options":["Monday","Tuesday","Wednesday","Friday"],"correct":2},{"question":"What type of stories does the writer like?","options":["Romance","Adventure","Horror","Mystery"],"correct":1},{"question":"What else does the library help with?","options":["Singing","Learning new things","Playing sports","Cooking"],"correct":1},{"question":"What is the library like?","options":["Noisy","Quiet","Crowded","Dark"],"correct":1}],"answers":[1,2,1,1,1],"answerExplanationVi":"1. Cô Hoa. 2. Thứ Tư. 3. Phiêu lưu. 4. Học điều mới. 5. Yên tĩnh.","discussionQuestions":["Bạn có thường đến thư viện không?","Bạn thích đọc thể loại sách nào?","Đọc sách mang lại lợi ích gì?"],"grammarFocus":{"point":"Countable vs Uncountable","explanation":"Danh từ đếm được (an apple, two apples) và không đếm được (water, rice, milk). Dùng \"some\" với không đếm được."},"shadowingSentences":["Our school library is a quiet place.","It has many books.","The librarian is Mrs. Hoa.","Every Wednesday, our class visits the library.","I borrow books to read at home."]},{"id":"a1_12","level":"A1","topic":"daily life","title":"A Rainy Day","titleVi":"Một Ngày Mưa","illustrationEmoji":"🌧️","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: một ngày mưa.","englishText":"Today it is **raining** outside. I cannot go out to play. I stay at home and do **indoor** activities. I help my mother clean the **house**. I **dust** the shelves and **water** the plants. Then I sit by the window and watch the **rain**. The rain makes a nice sound: pitter-patter. After the rain, the **sky** is clear. There is a beautiful **rainbow**. I love rainy days.","vietnameseText":"Hôm nay ngoài trời đang **mưa**. Tôi không thể ra ngoài chơi. Tôi ở nhà và làm các hoạt động **trong nhà**. Tôi giúp mẹ lau dọn **nhà cửa**. Tôi **phủi bụi** kệ và **tưới** cây. Sau đó tôi ngồi bên cửa sổ và ngắm **mưa**. Mưa tạo ra âm thanh dễ chịu: tí tách. Sau cơn mưa, **bầu trời** trong xanh. Có một **cầu vồng** tuyệt đẹp. Tôi yêu những ngày mưa.","vocabularyFocus":[{"word":"raining","vi":"đang mưa","example":""},{"word":"indoor","vi":"trong nhà","example":""},{"word":"dust","vi":"phủi bụi","example":""},{"word":"water","vi":"tưới cây","example":""},{"word":"rain","vi":"mưa","example":""},{"word":"sky","vi":"bầu trời","example":""},{"word":"rainbow","vi":"cầu vồng","example":""},{"word":"beautiful","vi":"đẹp","example":""}],"phrases":[{"en":"raining outside","vi":"ngoài trời đang mưa"},{"en":"indoor activities","vi":"hoạt động trong nhà"},{"en":"clean the house","vi":"lau dọn nhà cửa"},{"en":"sit by the window","vi":"ngồi bên cửa sổ"},{"en":"a beautiful rainbow","vi":"cầu vồng tuyệt đẹp"}],"comprehensionQuestions":[{"question":"Why can't the writer go outside?","options":["It is hot","It is raining","It is windy","It is dark"],"correct":1},{"question":"What does the writer do indoors?","options":["Reads books","Plays games","Helps clean the house","Sleeps"],"correct":2},{"question":"What sound does rain make?","options":["Boom-boom","Pitter-patter","Tick-tock","Ring-ring"],"correct":1},{"question":"What appears after the rain?","options":["Stars","Moon","Rainbow","Clouds"],"correct":2},{"question":"How does the writer feel about rainy days?","options":["Hates them","Loves them","Scared","Bored"],"correct":1}],"answers":[1,2,1,2,1],"answerExplanationVi":"1. Trời đang mưa. 2. Giúp lau dọn nhà. 3. Tí tách. 4. Cầu vồng. 5. Yêu thích.","discussionQuestions":["Bạn thích ngày nắng hay ngày mưa?","Bạn làm gì trong ngày mưa?","Tại sao mưa lại quan trọng?"],"grammarFocus":{"point":"Let's + Verb","explanation":"\"Let's\" (hãy cùng) + động từ. Ví dụ: \"Let's play soccer!\" (Hãy cùng chơi bóng đá!) \"Let's eat.\""},"shadowingSentences":["Today it is raining outside.","I stay at home and do indoor activities.","I help my mother clean the house.","The rain makes a nice sound.","After the rain, there is a beautiful rainbow."]},{"id":"a1_13","level":"A1","topic":"work","title":"My Dad's Job","titleVi":"Công Việc Của Bố Tôi","illustrationEmoji":"🔧","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: công việc của bố tôi.","englishText":"My dad is a **construction** worker. He **builds** houses and buildings. He gets up very **early** every morning. He goes to work at six o'clock. His work is **hard**, but he likes it. He says building houses makes people **happy**. Sometimes he brings home **wood** pieces. I make toys from them. I am **proud** of my dad. He works hard for our family.","vietnameseText":"Bố tôi là một công nhân **xây dựng**. Bố **xây** nhà và các tòa nhà. Bố dậy rất **sớm** mỗi sáng. Bố đi làm lúc sáu giờ. Công việc của bố rất **vất vả**, nhưng bố thích nó. Bố nói xây nhà làm mọi người **hạnh phúc**. Thỉnh thoảng bố mang về nhà những mảnh **gỗ**. Tôi làm đồ chơi từ chúng. Tôi rất **tự hào** về bố tôi. Bố làm việc chăm chỉ cho gia đình.","vocabularyFocus":[{"word":"construction","vi":"xây dựng","example":""},{"word":"build","vi":"xây","example":""},{"word":"early","vi":"sớm","example":""},{"word":"hard","vi":"vất vả","example":""},{"word":"wood","vi":"gỗ","example":""},{"word":"toys","vi":"đồ chơi","example":""},{"word":"proud","vi":"tự hào","example":""},{"word":"family","vi":"gia đình","example":""}],"phrases":[{"en":"a construction worker","vi":"công nhân xây dựng"},{"en":"gets up very early","vi":"dậy rất sớm"},{"en":"works hard","vi":"làm việc vất vả"},{"en":"builds houses","vi":"xây nhà"},{"en":"proud of my dad","vi":"tự hào về bố"}],"comprehensionQuestions":[{"question":"What does the writer's dad do?","options":["Teacher","Doctor","Construction worker","Engineer"],"correct":2},{"question":"What time does dad go to work?","options":["5:00","6:00","7:00","8:00"],"correct":1},{"question":"What does dad sometimes bring home?","options":["Food","Wood pieces","Tools","Books"],"correct":1},{"question":"What does the writer make from dad's materials?","options":["Furniture","Toys","Shelves","Pictures"],"correct":1},{"question":"How does the writer feel about dad?","options":["Proud","Worried","Sad","Angry"],"correct":0}],"answers":[2,1,1,1,0],"answerExplanationVi":"1. Công nhân xây dựng. 2. 6 giờ. 3. Gỗ. 4. Đồ chơi. 5. Tự hào.","discussionQuestions":["Bố mẹ bạn làm nghề gì?","Bạn có tự hào về bố mẹ không?","Bạn muốn làm nghề gì khi lớn?"],"grammarFocus":{"point":"Would like","explanation":"\"Would like\" (muốn, thích) – lịch sự hơn \"want\". Ví dụ: \"I would like some water.\" (Tôi muốn một ít nước.)"},"shadowingSentences":["My dad is a construction worker.","He builds houses and buildings.","He goes to work at six o'clock.","I am proud of my dad.","He works hard for our family."]},{"id":"a1_14","level":"A1","topic":"food","title":"Making Fresh Juice","titleVi":"Pha Nước Ép Tươi","illustrationEmoji":"🥤","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: pha nước ép tươi.","englishText":"I like to make **fresh juice** at home. It is easy and **healthy**. First, I **wash** the fruit: oranges, apples, or mangoes. Then I **cut** them into pieces. I **put** the pieces into a blender. I **add** a little sugar and ice. Finally, I **blend** everything. The juice is **sweet** and cold. My family loves my fresh juice. Making juice is fun and delicious.","vietnameseText":"Tôi thích **pha nước ép** tươi tại nhà. Nó dễ và **tốt cho sức khỏe**. Đầu tiên, tôi **rửa** trái cây: cam, táo hoặc xoài. Sau đó tôi **cắt** chúng thành miếng. Tôi **bỏ** các miếng vào máy xay sinh tố. Tôi **thêm** một ít đường và đá. Cuối cùng, tôi **xay** tất cả. Nước ép **ngọt** và mát lạnh. Gia đình tôi thích nước ép tươi của tôi. Pha nước ép vừa vui vừa ngon.","vocabularyFocus":[{"word":"fresh juice","vi":"nước ép tươi","example":""},{"word":"wash","vi":"rửa","example":""},{"word":"cut","vi":"cắt","example":""},{"word":"blender","vi":"máy xay sinh tố","example":""},{"word":"sugar","vi":"đường","example":""},{"word":"blend","vi":"xay","example":""},{"word":"sweet","vi":"ngọt","example":""},{"word":"delicious","vi":"ngon","example":""}],"phrases":[{"en":"make fresh juice","vi":"pha nước ép tươi"},{"en":"easy and healthy","vi":"dễ và tốt cho sức khỏe"},{"en":"cut into pieces","vi":"cắt thành miếng"},{"en":"add sugar and ice","vi":"thêm đường và đá"},{"en":"my family loves it","vi":"gia đình tôi thích nó"}],"comprehensionQuestions":[{"question":"What is the first step to make juice?","options":["Add sugar","Cut fruit","Wash fruit","Blend"],"correct":2},{"question":"What fruit is NOT mentioned?","options":["Oranges","Apples","Mangoes","Grapes"],"correct":3},{"question":"What do they add to the blender?","options":["Milk and honey","Sugar and ice","Salt and pepper","Yogurt"],"correct":1},{"question":"What is the final step?","options":["Wash","Cut","Add","Blend"],"correct":3},{"question":"How does the family like the juice?","options":["They love it","They hate it","They don't try it","Only mom likes it"],"correct":0}],"answers":[2,3,1,3,0],"answerExplanationVi":"1. Rửa trái cây. 2. Nho. 3. Đường và đá. 4. Xay. 5. Mọi người đều thích.","discussionQuestions":["Bạn có thích nước ép không?","Bạn biết làm món gì?","Món ăn tự làm nào bạn thích nhất?"],"grammarFocus":{"point":"There was/There were","explanation":"Quá khứ của \"there is/are\". \"There was\" (đã có) + số ít. \"There were\" (đã có) + số nhiều."},"shadowingSentences":["I like to make fresh juice at home.","First, I wash the fruit.","Then I cut them into pieces.","I add a little sugar and ice.","My family loves my fresh juice."]},{"id":"a1_15","level":"A1","topic":"school","title":"My Art Class","titleVi":"Lớp Học Vẽ Của Tôi","illustrationEmoji":"🎨","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: lớp học vẽ của tôi.","englishText":"I go to an **art** class every Saturday. The teacher shows us how to **draw** and **paint**. I am learning to use **watercolors**. Last week, I painted a **landscape** with mountains and a river. My teacher said it was **beautiful**. Art class helps me **relax** after a busy week. I can **express** my feelings through my paintings. I want to be an artist one day.","vietnameseText":"Tôi đi học **vẽ** vào mỗi thứ Bảy. Giáo viên hướng dẫn chúng tôi cách **vẽ** và **tô màu**. Tôi đang học sử dụng **màu nước**. Tuần trước, tôi vẽ một **bức tranh phong cảnh** với núi và sông. Giáo viên nói nó rất **đẹp**. Lớp vẽ giúp tôi **thư giãn** sau một tuần bận rộn. Tôi có thể **thể hiện** cảm xúc qua những bức vẽ. Tôi muốn trở thành một họa sĩ một ngày nào đó.","vocabularyFocus":[{"word":"art","vi":"nghệ thuật, hội họa","example":""},{"word":"draw","vi":"vẽ","example":""},{"word":"paint","vi":"tô màu","example":""},{"word":"watercolor","vi":"màu nước","example":""},{"word":"landscape","vi":"phong cảnh","example":""},{"word":"relax","vi":"thư giãn","example":""},{"word":"express","vi":"thể hiện","example":""},{"word":"artist","vi":"họa sĩ","example":""}],"phrases":[{"en":"art class","vi":"lớp học vẽ"},{"en":"draw and paint","vi":"vẽ và tô màu"},{"en":"every Saturday","vi":"mỗi thứ Bảy"},{"en":"said it was beautiful","vi":"nói nó rất đẹp"},{"en":"want to be an artist","vi":"muốn trở thành họa sĩ"}],"comprehensionQuestions":[{"question":"When does the writer have art class?","options":["Sunday","Saturday","Friday","Thursday"],"correct":1},{"question":"What did the writer paint last week?","options":["A portrait","A landscape","A still life","An abstract"],"correct":1},{"question":"What does the teacher use?","options":["Oil paints","Watercolors","Crayons","Chalk"],"correct":1},{"question":"How does art class help the writer?","options":["Learn math","Relax","Make friends","Earn money"],"correct":1},{"question":"What does the writer want to become?","options":["Teacher","Doctor","Artist","Engineer"],"correct":2}],"answers":[1,1,1,1,2],"answerExplanationVi":"1. Thứ Bảy. 2. Phong cảnh. 3. Màu nước. 4. Thư giãn. 5. Họa sĩ.","discussionQuestions":["Bạn có thích vẽ không?","Bạn có năng khiếu nghệ thuật không?","Bạn muốn học kỹ năng mới nào?"],"grammarFocus":{"point":"First, Then, After that, Finally","explanation":"Các từ chỉ trình tự: \"first\" (đầu tiên), \"then\" (sau đó), \"after that\" (sau đó nữa), \"finally\" (cuối cùng)."},"shadowingSentences":["I go to an art class every Saturday.","I am learning to use watercolors.","Art class helps me relax.","I can express my feelings through art.","I want to be an artist one day."]},{"id":"a1_16","level":"A1","topic":"daily life","title":"Helping at Home","titleVi":"Giúp Đỡ Ở Nhà","illustrationEmoji":"🧹","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: giúp đỡ ở nhà.","englishText":"I help my parents at home every day. I sweep the **floor** and **wash** the dishes. I also **water** the plants in the garden. On weekends, I help my dad **wash** the car. Helping at home is **important**. It makes my parents **happy**. I also learn to be **responsible**. My mother says I am a good **helper**. I feel proud when I help my family.","vietnameseText":"Tôi giúp đỡ bố mẹ ở nhà mỗi ngày. Tôi quét **sàn nhà** và **rửa** bát đĩa. Tôi cũng **tưới** cây trong vườn. Vào cuối tuần, tôi giúp bố **rửa** xe. Giúp việc nhà rất **quan trọng**. Nó làm bố mẹ tôi **vui**. Tôi cũng học cách **có trách nhiệm**. Mẹ tôi nói tôi là một **người giúp đỡ** tốt. Tôi cảm thấy tự hào khi giúp đỡ gia đình.","vocabularyFocus":[{"word":"sweep","vi":"quét","example":""},{"word":"wash dishes","vi":"rửa bát","example":""},{"word":"water plants","vi":"tưới cây","example":""},{"word":"wash the car","vi":"rửa xe","example":""},{"word":"important","vi":"quan trọng","example":""},{"word":"responsible","vi":"có trách nhiệm","example":""},{"word":"helper","vi":"người giúp đỡ","example":""},{"word":"proud","vi":"tự hào","example":""}],"phrases":[{"en":"help my parents at home","vi":"giúp đỡ bố mẹ ở nhà"},{"en":"sweep the floor","vi":"quét sàn nhà"},{"en":"water the plants","vi":"tưới cây"},{"en":"good helper","vi":"người giúp đỡ tốt"},{"en":"learn to be responsible","vi":"học cách có trách nhiệm"}],"comprehensionQuestions":[{"question":"What does the writer do every day?","options":["Plays outside","Helps at home","Studies","Sleeps"],"correct":1},{"question":"What does the writer do on weekends?","options":["Plays games","Washes the car","Visits friends","Watches movies"],"correct":1},{"question":"Why is helping at home important?","options":["It pays money","It makes parents happy","It is fun","It is easy"],"correct":1},{"question":"What does the writer learn from helping?","options":["To be responsible","To be fast","To be strong","To be rich"],"correct":0},{"question":"What does the mother call the writer?","options":["Good boy","Good helper","Good student","Good friend"],"correct":1}],"answers":[1,1,1,0,1],"answerExplanationVi":"1. Giúp việc nhà. 2. Rửa xe. 3. Làm bố mẹ vui. 4. Có trách nhiệm. 5. Good helper.","discussionQuestions":["Bạn giúp bố mẹ việc gì ở nhà?","Làm việc nhà có lợi ích gì?","Bạn nghĩ trẻ em nên làm việc nhà không?"],"grammarFocus":{"point":"Too / Either","explanation":"\"Too\" (cũng vậy) dùng trong câu khẳng định. \"Either\" dùng trong câu phủ định. \"I like it too.\" \"I don't like it either.\""},"shadowingSentences":["I help my parents at home every day.","I sweep the floor and wash the dishes.","Helping at home is important.","I learn to be responsible.","I feel proud when I help my family."]},{"id":"a1_17","level":"A1","topic":"travel","title":"A Visit to the Zoo","titleVi":"Đi Thăm Sở Thú","illustrationEmoji":"🦁","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: đi thăm sở thú.","englishText":"Last Sunday, our class went to the **zoo**. I saw many animals: **tigers**, **elephants**, monkeys, and giraffes. The monkeys were very **funny**. They jumped and made **noises**. The elephants were **huge** but gentle. A peacock showed its **colorful** feathers. I **fed** the deer with carrots. I learned many new things about animals. The zoo is an **amazing** place to visit.","vietnameseText":"Chủ nhật tuần trước, lớp chúng tôi đã đi **sở thú**. Tôi thấy nhiều loài vật: **hổ**, **voi**, khỉ và hươu cao cổ. Những chú khỉ rất **buồn cười**. Chúng nhảy và gây **ồn ào**. Những chú voi **to lớn** nhưng hiền lành. Một con công xòe bộ lông **đầy màu sắc** của nó. Tôi đã **cho** hươu ăn cà rốt. Tôi học được nhiều điều mới về động vật. Sở thú là một nơi **tuyệt vời** để tham quan.","vocabularyFocus":[{"word":"zoo","vi":"sở thú","example":""},{"word":"tiger","vi":"hổ","example":""},{"word":"elephant","vi":"voi","example":""},{"word":"monkey","vi":"khỉ","example":""},{"word":"noise","vi":"ồn ào","example":""},{"word":"huge","vi":"to lớn","example":""},{"word":"colorful","vi":"đầy màu sắc","example":""},{"word":"amazing","vi":"tuyệt vời","example":""}],"phrases":[{"en":"went to the zoo","vi":"đi sở thú"},{"en":"many animals","vi":"nhiều loài vật"},{"en":"very funny","vi":"rất buồn cười"},{"en":"made noises","vi":"gây ồn ào"},{"en":"learned many new things","vi":"học được nhiều điều mới"}],"comprehensionQuestions":[{"question":"What animals did the writer see at the zoo?","options":["Dogs and cats","Tigers, elephants, monkeys","Birds and fish","Horses and cows"],"correct":1},{"question":"What were the monkeys doing?","options":["Jumping and making noise","Sleeping","Eating","Swimming"],"correct":0},{"question":"What did the peacock show?","options":["Its tail","Its colorful feathers","Its wings","Its beak"],"correct":1},{"question":"What did the writer feed to the deer?","options":["Grass","Carrots","Leaves","Bread"],"correct":1},{"question":"How did the writer feel about the zoo?","options":["Bored","Scared","Amazed","Tired"],"correct":2}],"answers":[1,0,1,1,2],"answerExplanationVi":"1. Hổ, voi, khỉ. 2. Nhảy và ồn ào. 3. Lông sặc sỡ. 4. Cà rốt. 5. Tuyệt vời.","discussionQuestions":["Con vật yêu thích của bạn là gì?","Bạn đã đến sở thú bao giờ chưa?","Bạn muốn bảo vệ động vật như thế nào?"],"grammarFocus":{"point":"Some / Any","explanation":"\"Some\" dùng trong câu khẳng định. \"Any\" dùng trong câu phủ định và nghi vấn. \"I have some books.\" \"Do you have any?\""},"shadowingSentences":["Last Sunday, our class went to the zoo.","I saw many animals.","The monkeys were very funny.","The elephants were huge but gentle.","The zoo is an amazing place."]},{"id":"a1_18","level":"A1","topic":"food","title":"My Grandma's Cooking","titleVi":"Món Nấu Của Bà Tôi","illustrationEmoji":"🍲","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: món nấu của bà tôi.","englishText":"My grandma is an **amazing** cook. She makes the best **pho** and **spring rolls**. Her food is always **delicious**. When I visit her, the kitchen **smells** wonderful. She teaches me how to **roll** spring rolls. She says cooking needs **patience**. I help her **wash** vegetables and **stir** the pot. Eating my grandma's food makes me feel **warm** and loved.","vietnameseText":"Bà tôi là một **đầu bếp** tuyệt vời. Bà nấu **phở** và **nem rán** ngon nhất. Đồ ăn của bà luôn **ngon tuyệt**. Khi tôi thăm bà, căn bếp **thơm** phức tuyệt vời. Bà dạy tôi cách **cuốn** nem rán. Bà nói nấu ăn cần có **kiên nhẫn**. Tôi giúp bà **rửa** rau và **khuấy** nồi. Ăn đồ bà nấu làm tôi cảm thấy **ấm áp** và được yêu thương.","vocabularyFocus":[{"word":"grandma","vi":"bà","example":""},{"word":"amazing","vi":"tuyệt vời","example":""},{"word":"cook","vi":"đầu bếp, nấu ăn","example":""},{"word":"spring rolls","vi":"nem rán","example":""},{"word":"smell","vi":"thơm","example":""},{"word":"roll","vi":"cuốn","example":""},{"word":"patience","vi":"kiên nhẫn","example":""},{"word":"stir","vi":"khuấy","example":""}],"phrases":[{"en":"an amazing cook","vi":"đầu bếp tuyệt vời"},{"en":"makes the best pho","vi":"nấu phở ngon nhất"},{"en":"teaches me to cook","vi":"dạy tôi nấu ăn"},{"en":"wash vegetables","vi":"rửa rau"},{"en":"feels warm and loved","vi":"cảm thấy ấm áp và yêu thương"}],"comprehensionQuestions":[{"question":"What does grandma make best?","options":["Cakes","Pho and spring rolls","Salad","Soup"],"correct":1},{"question":"What does grandma say cooking needs?","options":["Speed","Patience","Money","Talent"],"correct":1},{"question":"What does the writer help with?","options":["Washing vegetables and stirring","Chopping meat","Setting the table","Serving food"],"correct":0},{"question":"How does grandma's food make the writer feel?","options":["Full","Warm and loved","Tired","Excited"],"correct":1},{"question":"What does the writer learn from grandma?","options":["To read","To cook","To sing","To dance"],"correct":1}],"answers":[1,1,0,1,1],"answerExplanationVi":"1. Phở và nem rán. 2. Kiên nhẫn. 3. Rửa rau và khuấy nồi. 4. Ấm áp và yêu thương. 5. Nấu ăn.","discussionQuestions":["Bà bạn nấu món gì ngon nhất?","Bạn có thích nấu ăn không?","Món ăn kỷ niệm tuổi thơ của bạn?"],"grammarFocus":{"point":"Comparative with \"more\"","explanation":"Với tính từ dài, dùng \"more + adj\". Ví dụ: \"She is more beautiful.\" \"This book is more interesting.\""},"shadowingSentences":["My grandma is an amazing cook.","She makes the best pho and spring rolls.","She teaches me how to cook.","Cooking needs patience.","Eating grandma's food makes me feel warm."]},{"id":"a1_19","level":"A1","topic":"family","title":"My Two Sisters","titleVi":"Hai Chị Gái Của Tôi","illustrationEmoji":"👩‍👧‍👧","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: hai chị gái của tôi.","englishText":"I have two **sisters**. Their names are Mai and An. Mai is fifteen years old. An is eight. We **share** a bedroom. Sometimes we **argue** about what to watch on TV. But we always **forgive** each other. In the evening, we **talk** about our day. My sisters are my best **friends**. I am lucky to have them.","vietnameseText":"Tôi có hai **chị gái**. Tên họ là Mai và An. Mai mười lăm tuổi. An tám tuổi. Chúng tôi **ở chung** một phòng ngủ. Đôi khi chúng tôi **cãi nhau** về việc xem gì trên TV. Nhưng chúng tôi luôn **tha thứ** cho nhau. Vào buổi tối, chúng tôi **kể** cho nhau về ngày của mình. Các chị tôi là những **người bạn** thân nhất của tôi. Tôi thật may mắn khi có họ.","vocabularyFocus":[{"word":"sisters","vi":"chị em gái","example":""},{"word":"share","vi":"ở chung, chia sẻ","example":""},{"word":"argue","vi":"cãi nhau","example":""},{"word":"forgive","vi":"tha thứ","example":""},{"word":"talk about","vi":"kể về","example":""},{"word":"friends","vi":"bạn bè","example":""},{"word":"lucky","vi":"may mắn","example":""},{"word":"bedroom","vi":"phòng ngủ","example":""}],"phrases":[{"en":"two sisters","vi":"hai chị gái"},{"en":"share a bedroom","vi":"ở chung phòng ngủ"},{"en":"argue about TV","vi":"cãi nhau về TV"},{"en":"forgive each other","vi":"tha thứ cho nhau"},{"en":"my best friends","vi":"những người bạn tốt nhất của tôi"}],"comprehensionQuestions":[{"question":"How many sisters does the writer have?","options":["One","Two","Three","Four"],"correct":1},{"question":"How old is An?","options":["Eight","Ten","Twelve","Fifteen"],"correct":0},{"question":"What do the sisters argue about?","options":["Food","TV","Clothes","Homework"],"correct":1},{"question":"What do they do in the evening?","options":["Watch TV","Talk about their day","Play games","Study"],"correct":1},{"question":"How does the writer feel about their sisters?","options":["Annoyed","Lucky to have them","Jealous","Indifferent"],"correct":1}],"answers":[1,0,1,1,1],"answerExplanationVi":"1. Hai chị gái. 2. Tám tuổi. 3. Về TV. 4. Kể về ngày của mình. 5. May mắn.","discussionQuestions":["Bạn có anh chị em không?","Bạn có thân với họ không?","Sống với anh chị em có gì vui?"],"grammarFocus":{"point":"Superlatives (most)","explanation":"So sánh nhất với \"the most\". Ví dụ: \"This is the most interesting book.\" (Đây là cuốn sách thú vị nhất.)"},"shadowingSentences":["I have two sisters.","Their names are Mai and An.","We share a bedroom.","We talk about our day in the evening.","My sisters are my best friends."]},{"id":"a1_20","level":"A1","topic":"daily life","title":"My Pet Dog","titleVi":"Chú Chó Cưng Của Tôi","illustrationEmoji":"🐕","estimatedMinutes":4,"xpReward":40,"summaryVi":"Câu chuyện trình độ A1: chú chó cưng của tôi.","englishText":"I have a pet **dog**. His name is Lucky. He is small and **brown**. He has long **ears** and a short tail. Lucky **wags** his tail when he sees me. Every morning, I **feed** him. I also take him for a **walk** in the park. Lucky likes to **run** and catch a ball. He is very **friendly**. He **licks** my face when I come home. Lucky is not just a pet — he is my best **friend**.","vietnameseText":"Tôi có một **chú chó** cưng. Tên nó là Lucky. Nó nhỏ và có màu **nâu**. Nó có **tai** dài và đuôi ngắn. Lucky **vẫy** đuôi khi thấy tôi. Mỗi buổi sáng, tôi **cho** nó ăn. Tôi cũng dẫn nó đi **dạo** trong công viên. Lucky thích **chạy** và bắt bóng. Nó rất **thân thiện**. Nó **liếm** mặt tôi khi tôi về nhà. Lucky không chỉ là thú cưng — nó là người bạn thân nhất của tôi.","vocabularyFocus":[{"word":"dog","vi":"chó","example":""},{"word":"brown","vi":"màu nâu","example":""},{"word":"ears","vi":"tai","example":""},{"word":"wag","vi":"vẫy (đuôi)","example":""},{"word":"feed","vi":"cho ăn","example":""},{"word":"walk","vi":"đi dạo","example":""},{"word":"friendly","vi":"thân thiện","example":""},{"word":"lick","vi":"liếm","example":""}],"phrases":[{"en":"my pet dog","vi":"chú chó cưng của tôi"},{"en":"his name is Lucky","vi":"tên nó là Lucky"},{"en":"take him for a walk","vi":"dẫn nó đi dạo"},{"en":"catch a ball","vi":"bắt bóng"},{"en":"my best friend","vi":"người bạn thân nhất của tôi"}],"comprehensionQuestions":[{"question":"What is the dog's name?","options":["Brown","Lucky","Spot","Max"],"correct":1},{"question":"What color is the dog?","options":["Black","White","Brown","Gray"],"correct":2},{"question":"What does the writer do every morning?","options":["Plays with Lucky","Feeds Lucky","Washes Lucky","Teaches Lucky"],"correct":1},{"question":"What does Lucky do when the writer comes home?","options":["Barks","Sleeps","Licks his face","Runs away"],"correct":2},{"question":"What is Lucky good at?","options":["Singing","Dancing","Catching a ball","Reading"],"correct":2}],"answers":[1,2,1,2,2],"answerExplanationVi":"1. Tên là Lucky. 2. Màu nâu. 3. Cho Lucky ăn. 4. Liếm mặt. 5. Bắt bóng.","discussionQuestions":["Bạn có thú cưng không?","Bạn muốn nuôi con vật gì?","Tại sao thú cưng là bạn tốt?"],"grammarFocus":{"point":"Possessive Adjectives","explanation":"Tính từ sở hữu: \"my\" (của tôi), \"his\" (của nó), \"her\" (của cô ấy), \"our\" (của chúng tôi). Ví dụ: \"His name is Lucky.\""},"shadowingSentences":["I have a pet dog.","His name is Lucky.","Every morning I feed him.","I take him for a walk.","He is my best friend."]}];
